enum QuestionType { mcq, trueFalse, shortAnswer }
class QuestionModel { final String id,examId,text,type,correctAnswer; final List<String> options; final double points; final int order; const QuestionModel({required this.id,required this.examId,required this.text,required this.type,required this.correctAnswer,this.options=const [],this.points=1,this.order=0}); QuestionType get questionType=>QuestionType.values.firstWhere((e)=>e.name==type,orElse:()=>QuestionType.mcq); Map<String,dynamic> toMap()=>{'examId':examId,'text':text,'type':type,'correctAnswer':correctAnswer,'options':options,'points':points,'order':order}; factory QuestionModel.fromMap(String id,Map<String,dynamic> m)=>QuestionModel(id:id,examId:m['examId']??'',text:m['text']??'',type:m['type']??'mcq',correctAnswer:m['correctAnswer']??'',options:List<String>.from(m['options']??const []),points:(m['points']??1).toDouble(),order:m['order']??0); }